[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "budget-analysis-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "budget-analysis-surface",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "properties": {
            "spacing": "medium",
            "padding": {
              "all": "medium"
            }
          },
          "children": [
            {
              "id": "header_row",
              "component": "Row",
              "properties": {
                "spacing": "medium",
                "verticalAlignment": "center"
              },
              "children": [
                {
                  "id": "header_icon",
                  "component": "Icon",
                  "properties": {
                    "source": "/icons/finance.png",
                    "size": "large"
                  }
                },
                {
                  "id": "header_text",
                  "component": "Text",
                  "properties": {
                    "text": "Your Monthly Budget Analysis",
                    "style": "title"
                  }
                }
              ]
            },
            {
              "id": "overview_title",
              "component": "Text",
              "properties": {
                "text": "Your Monthly Budget Overview:",
                "style": "heading"
              }
            },
            {
              "id": "budget_table",
              "component": "Column",
              "properties": {
                "spacing": "small"
              },
              "children": [
                {
                  "id": "rent_row",
                  "component": "Row",
                  "children": [
                    {
                      "id": "rent_label",
                      "component": "Text",
                      "properties": {
                        "text": "Rent"
                      },
                      "layout": {
                        "grow": 1
                      }
                    },
                    {
                      "id": "rent_value",
                      "component": "Text",
                      "properties": {
                        "text": "$2,100"
                      }
                    }
                  ]
                },
                {
                  "id": "groceries_row",
                  "component": "Row",
                  "children": [
                    {
                      "id": "groceries_label",
                      "component": "Text",
                      "properties": {
                        "text": "Groceries"
                      },
                      "layout": {
                        "grow": 1
                      }
                    },
                    {
                      "id": "groceries_value",
                      "component": "Text",
                      "properties": {
                        "text": "$650"
                      }
                    }
                  ]
                },
                {
                  "id": "dining_row",
                  "component": "Row",
                  "children": [
                    {
                      "id": "dining_label",
                      "component": "Text",
                      "properties": {
                        "text": "Dining Out"
                      },
                      "layout": {
                        "grow": 1
                      }
                    },
                    {
                      "id": "dining_value",
                      "component": "Text",
                      "properties": {
                        "text": "$400"
                      }
                    }
                  ]
                },
                {
                  "id": "utilities_row",
                  "component": "Row",
                  "children": [
                    {
                      "id": "utilities_label",
                      "component": "Text",
                      "properties": {
                        "text": "Utilities"
                      },
                      "layout": {
                        "grow": 1
                      }
                    },
                    {
                      "id": "utilities_value",
                      "component": "Text",
                      "properties": {
                        "text": "$280"
                      }
                    }
                  ]
                },
                {
                  "id": "internet_row",
                  "component": "Row",
                  "children": [
                    {
                      "id": "internet_label",
                      "component": "Text",
                      "properties": {
                        "text": "Internet"
                      },
                      "layout": {
                        "grow": 1
                      }
                    },
                    {
                      "id": "internet_value",
                      "component": "Text",
                      "properties": {
                        "text": "$80"
                      }
                    }
                  ]
                },
                {
                  "id": "streaming_row",
                  "component": "Row",
                  "children": [
                    {
                      "id": "streaming_label",
                      "component": "Text",
                      "properties": {
                        "text": "Streaming Services"
                      },
                      "layout": {
                        "grow": 1
                      }
                    },
                    {
                      "id": "streaming_value",
                      "component": "Text",
                      "properties": {
                        "text": "$120"
                      }
                    }
                  ]
                },
                {
                  "id": "gym_row",
                  "component": "Row",
                  "children": [
                    {
                      "id": "gym_label",
                      "component": "Text",
                      "properties": {
                        "text": "Gym"
                      },
                      "layout": {
                        "grow": 1
                      }
                    },
                    {
                      "id": "gym_value",
                      "component": "Text",
                      "properties": {
                        "text": "$100"
                      }
                    }
                  ]
                },
                {
                  "id": "transport_row",
                  "component": "Row",
                  "children": [
                    {
                      "id": "transport_label",
                      "component": "Text",
                      "properties": {
                        "text": "Transportation"
                      },
                      "layout": {
                        "grow": 1
                      }
                    },
                    {
                      "id": "transport_value",
                      "component": "Text",
                      "properties": {
                        "text": "$350"
                      }
                    }
                  ]
                },
                {
                  "id": "misc_row",
                  "component": "Row",
                  "children": [
                    {
                      "id": "misc_label",
                      "component": "Text",
                      "properties": {
                        "text": "Miscellaneous"
                      },
                      "layout": {
                        "grow": 1
                      }
                    },
                    {
                      "id": "misc_value",
                      "component": "Text",
                      "properties": {
                        "text": "$200"
                      }
                    }
                  ]
                },
                {
                  "id": "budget_divider",
                  "component": "Divider"
                },
                {
                  "id": "total_row",
                  "component": "Row",
                  "children": [
                    {
                      "id": "total_label",
                      "component": "Text",
                      "properties": {
                        "text": "Total Monthly Expenses",
                        "weight": "bold"
                      },
                      "layout": {
                        "grow": 1
                      }
                    },
                    {
                      "id": "total_value",
                      "component": "Text",
                      "properties": {
                        "text": "$4,280",
                        "weight": "bold"
                      }
                    }
                  ]
                }
              ]
            },
            {
              "id": "savings_goal_card",
              "component": "Card",
              "children": [
                {
                  "id": "savings_goal_row",
                  "component": "Row",
                  "properties": {
                    "spacing": "medium",
                    "verticalAlignment": "center"
                  },
                  "children": [
                    {
                      "id": "savings_icon",
                      "component": "Icon",
                      "properties": {
                        "source": "/icons/piggy-bank.png",
                        "size": "large"
                      }
                    },
                    {
                      "id": "savings_goal_text",
                      "component": "Text",
                      "properties": {
                        "text": "Savings Goal: Based on your budget, we've identified three areas where you can save at least $200 per month without significantly impacting essential needs."
                      }
                    }
                  ]
                }
              ]
            },
            {
              "id": "areas_to_save_title",
              "component": "Text",
              "properties": {
                "text": "Three Areas to Save:",
                "style": "heading"
              }
            },
            {
              "id": "savings_tabs",
              "component": "Tabs",
              "children": [
                {
                  "id": "tab_dining",
                  "component": "Tab",
                  "properties": {
                    "label": "Dining Out"
                  },
                  "children": [
                    {
                      "id": "dining_content",
                      "component": "Column",
                      "properties": {
                        "spacing": "small",
                        "padding": {
                          "top": "medium"
                        }
                      },
                      "children": [
                        {
                          "id": "dining_summary",
                          "component": "Text",
                          "properties": {
                            "text": "Summary: Reduce dining out expenses by focusing on home-cooked meals and packed lunches."
                          }
                        },
                        {
                          "id": "dining_savings",
                          "component": "Text",
                          "properties": {
                            "text": "Potential Savings: $100 (reducing from $400 to $300)",
                            "weight": "bold"
                          }
                        },
                        {
                          "id": "dining_tip",
                          "component": "Text",
                          "properties": {
                            "text": "Actionable Tip: Plan to cook at home more often. Consider packing your lunch for work/school at least 2-3 times a week instead of buying it."
                          }
                        }
                      ]
                    }
                  ]
                },
                {
                  "id": "tab_streaming",
                  "component": "Tab",
                  "properties": {
                    "label": "Streaming Services"
                  },
                  "children": [
                    {
                      "id": "streaming_content",
                      "component": "Column",
                      "properties": {
                        "spacing": "small",
                        "padding": {
                          "top": "medium"
                        }
                      },
                      "children": [
                        {
                          "id": "streaming_summary",
                          "component": "Text",
                          "properties": {
                            "text": "Summary: Evaluate and optimize your streaming subscriptions to cut unnecessary costs."
                          }
                        },
                        {
                          "id": "streaming_savings",
                          "component": "Text",
                          "properties": {
                            "text": "Potential Savings: $50 (reducing from $120 to $70)",
                            "weight": "bold"
                          }
                        },
                        {
                          "id": "streaming_tip",
                          "component": "Text",
                          "properties": {
                            "text": "Actionable Tip: Review all active subscriptions. Cancel any services you rarely use, or consider rotating services month-to-month. Look into ad-supported tiers if available and suitable."
                          }
                        }
                      ]
                    }
                  ]
                },
                {
                  "id": "tab_groceries",
                  "component": "Tab",
                  "properties": {
                    "label": "Groceries"
                  },
                  "children": [
                    {
                      "id": "groceries_content",
                      "component": "Column",
                      "properties": {
                        "spacing": "small",
                        "padding": {
                          "top": "medium"
                        }
                      },
                      "children": [
                        {
                          "id": "groceries_summary",
                          "component": "Text",
                          "properties": {
                            "text": "Summary: Implement smarter grocery shopping habits to reduce your weekly spend."
                          }
                        },
                        {
                          "id": "groceries_savings",
                          "component": "Text",
                          "properties": {
                            "text": "Potential Savings: $50 (reducing from $650 to $600)",
                            "weight": "bold"
                          }
                        },
                        {
                          "id": "groceries_tip",
                          "component": "Text",
                          "properties": {
                            "text": "Actionable Tip: Create a weekly meal plan before you shop, make a detailed grocery list, and stick to it to avoid impulse purchases. Compare prices and buy generic brands for staples."
                          }
                        }
                      ]
                    }
                  ]
                }
              ]
            },
            {
              "id": "total_savings_text",
              "component": "Text",
              "properties": {
                "text": "Total Potential Savings: $100 + $50 + $50 = $200",
                "style": "subheading",
                "weight": "bold",
                "horizontalAlignment": "center"
              }
            },
            {
              "id": "actions_divider",
              "component": "Divider"
            },
            {
              "id": "actions_title",
              "component": "Text",
              "properties": {
                "text": "Quick Actions",
                "style": "heading"
              }
            },
            {
              "id": "actions_row",
              "component": "Row",
              "properties": {
                "spacing": "medium",
                "horizontalAlignment": "center"
              },
              "children": [
                {
                  "id": "button_budget",
                  "component": "Button",
                  "properties": {
                    "label": "Create a Detailed Budget Plan",
                    "action": {
                      "functionCall": {
                        "call": "openUrl",
                        "args": [
                          "https://www.example.com/budget-template"
                        ]
                      }
                    }
                  }
                },
                {
                  "id": "button_meal",
                  "component": "Button",
                  "properties": {
                    "label": "Find Meal Planning Resources",
                    "action": {
                      "functionCall": {
                        "call": "openUrl",
                        "args": [
                          "https://www.example.com/meal-planning-tips"
                        ]
                      }
                    }
                  }
                },
                {
                  "id": "button_streaming",
                  "component": "Button",
                  "properties": {
                    "label": "Compare Streaming Services",
                    "action": {
                      "functionCall": {
                        "call": "openUrl",
                        "args": [
                          "https://www.example.com/streaming-comparison"
                        ]
                      }
                    }
                  }
                }
              ]
            }
          ]
        }
      ]
    }
  }
]
